import argparse, csv, json
from decimal import Decimal, InvalidOperation

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('payload')
    parsed = parser.parse_args()
    try:
        json.loads(parsed.payload)
    except Exception:
        pass

    regions = {}
    with open('/inputs/customers.csv', newline='') as f:
        for row in csv.DictReader(f):
            cid = row.get('customer_id', '').strip()
            region = row.get('region', '').strip()
            if cid:
                regions[cid] = region

    total = Decimal('0')
    with open('/inputs/orders.csv', newline='') as f:
        for row in csv.DictReader(f):
            cid = row.get('customer_id', '').strip()
            if cid in regions and regions[cid] == 'west':
                try:
                    total += Decimal(row.get('amount', '').strip())
                except InvalidOperation:
                    continue

    if total == total.to_integral():
        print(int(total))
    else:
        print(total)


if __name__ == '__main__':
    main()

import argparse
import csv
import json

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    config = json.loads(args.payload)
    path = config.get("path", "/inputs/ledger.csv")

    total = 0.0
    with open(path, newline="", encoding="utf-8") as f:
        reader = csv.reader(f)
        header = None
        idx = None
        for row in reader:
            if not row:
                continue
            if header is None:
                header = [h.strip().lower() for h in row]
                if "amount" in header:
                    idx = header.index("amount")
                continue
            try:
                raw = row[idx] if idx is not None else row[0]
            except IndexError:
                continue
            raw = raw.strip().replace("$", "").replace(",", "")
            if not raw:
                continue
            try:
                total += float(raw)
            except ValueError:
                continue

    print("{:.2f}".format(total))

if __name__ == "__main__":
    main()

import argparse
import csv
import json


def parse_amount(value):
    value = value.strip()
    if not value:
        return 0.0
    cleaned = value.replace("$", "").replace(",", "").strip()
    if cleaned == "" or cleaned == "-":
        return 0.0
    return float(cleaned)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    config = json.loads(args.payload)
    path = config["path"]
    total = 0.0
    with open(path, newline="") as f:
        reader = csv.DictReader(f)
        for row in reader:
            row = {k.lower().strip() if k else k: v for k, v in row.items()}
            raw = row.get("amount", "").strip()
            if not raw:
                continue
            total += parse_amount(raw)
    print(f"{total:.2f}")


if __name__ == "__main__":
    main()

import argparse
import csv
import json
from datetime import date


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    payload = json.loads(args.payload)
    path = payload["path"]

    found = []
    with open(path, newline="", encoding="utf-8") as handle:
        reader = csv.DictReader(handle)
        for row in reader:
            value = (row.get("date") or "").strip()
            if not value:
                continue
            if len(value) == 10 and value[4] == "-" and value[7] == "-":
                try:
                    found.append(date.fromisoformat(value))
                except ValueError:
                    continue

    if not found:
        print(0)
    else:
        print((max(found) - min(found)).days)


if __name__ == "__main__":
    main()

import argparse
import csv
import json


def parse_amount(text):
    text = text.strip()
    if not text:
        return 0.0
    text = text.replace("$", "").replace(",", "")
    return float(text)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    config = json.loads(args.payload)
    path = config["path"]

    with open(path, newline="", encoding="utf-8") as f:
        lines = [line for line in f if line.strip()]

    total = 0.0
    if lines:
        reader = csv.reader(lines)
        rows = list(reader)
        if rows:
            header = rows[0]
            amount_idx = None
            for i, col in enumerate(header):
                if col.strip().lower() == "amount":
                    amount_idx = i
                    break
            if amount_idx is None:
                amount_idx = len(header) - 1

            for row in rows[1:]:
                if amount_idx < len(row):
                    value = row[amount_idx].strip()
                    if value:
                        total += parse_amount(value)

    print(f"{total:.2f}")


if __name__ == "__main__":
    main()

import argparse
import csv
import json
from decimal import Decimal, InvalidOperation

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('payload')
    args = parser.parse_args()

    config = json.loads(args.payload) if args.payload.strip() else {}
    path = config.get('path', '/inputs/ledger.csv')

    total = Decimal('0')

    with open(path, newline='', encoding='utf-8') as f:
        reader = csv.reader(f)
        header = None
        for row in reader:
            if any(cell.strip() for cell in row):
                header = [cell.strip().lower() for cell in row]
                break

        if header is None:
            print('0.00')
            return

        try:
            amount_idx = header.index('amount')
        except ValueError:
            print('0.00')
            return

        for row in reader:
            if not any(cell.strip() for cell in row):
                continue
            raw = row[amount_idx] if amount_idx < len(row) else ''
            raw = raw.strip().replace('$', '').replace(',', '')
            if not raw:
                continue
            try:
                total += Decimal(raw)
            except InvalidOperation:
                continue

    print(f'{total:.2f}')

if __name__ == '__main__':
    main()

import argparse
import csv
import json
import re

def net_total(path):
    total = 0.0
    with open(path, newline='', encoding='utf-8-sig') as f:
        reader = csv.DictReader(f)
        amount_key = None
        if reader.fieldnames:
            for name in reader.fieldnames:
                if name.strip().lower() == 'amount':
                    amount_key = name
                    break
        if amount_key is None:
            return total
        for row in reader:
            raw = row.get(amount_key)
            if raw is None:
                continue
            raw = raw.strip()
            if raw == '':
                continue
            cleaned = re.sub(r"[\s,$]", "", raw)
            if cleaned == '':
                continue
            negative = cleaned.startswith('(') or cleaned.startswith('-')
            cleaned = cleaned.strip('()')
            try:
                value = float(cleaned)
            except ValueError:
                continue
            if negative:
                value = -abs(value)
            total += value
    return total

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    config = json.loads(args.payload)
    path = config.get("path", "/inputs/ledger.csv")
    print("{:.2f}".format(net_total(path)))

if __name__ == "__main__":
    main()

import argparse
import json

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = json.loads(parser.parse_args().payload)
    latest = {}
    with open(args["path"], "r", encoding="utf-8") as f:
        for line in f:
            if not line.strip():
                continue
            rec = json.loads(line)
            user = rec["user"]
            ts = rec["ts"]
            if user not in latest or ts >= latest[user][0]:
                latest[user] = (ts, rec["action"])
    count = sum(1 for _, action in latest.values() if action == "logout")
    print(count, end="")

if __name__ == "__main__":
    main()
